import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { redeemChipHandler } from "../handlers/redeemChipHandler";
import type { ApiError } from "../runtime/client";
import type { RedeemChipRequest } from "../types/RedeemChipRequest";

type Data = Awaited<ReturnType<typeof redeemChipHandler>>;
type Vars = RedeemChipRequest;

export function useRedeemChip(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => redeemChipHandler(vars),
    ...options,
  });
}
